import React from "react";

function LandingSearchBox() {
  return (
    <div className="w-full h-60 flex justify-center items-center">
      <div className="w-[95%] max-w-6xl bg-white/80 backdrop-blur-md shadow-lg rounded-2xl p-6 border border-white/30">
        <div className="grid grid-cols-5 gap-4 h-full">
          
          {/* Блок 1 — Select Makes */}
          <div className="bg-white/90 rounded-lg shadow p-4 flex flex-col justify-between">
            <label className="text-sm font-medium text-gray-700 mb-2">Select Makes</label>
            <select className="mt-auto p-2 rounded border border-gray-300 focus:outline-none focus:ring-2 focus:ring-blue-400">
              <option value="">-- Choose --</option>
              <option value="audi">Audi</option>
              <option value="bmw">BMW</option>
              <option value="mercedes">Mercedes</option>
              <option value="toyota">Toyota</option>
              <option value="honda">Honda</option>
              <option value="ford">Ford</option>
            </select>
          </div>

          {/* Остальные 4 блока-заглушки */}
          <div className="bg-white/90 rounded-lg shadow p-4 text-center">Блок 2</div>
          <div className="bg-white/90 rounded-lg shadow p-4 text-center">Блок 3</div>
          <div className="bg-white/90 rounded-lg shadow p-4 text-center">Блок 4</div>
          <div className="bg-white/90 rounded-lg shadow p-4 text-center">Блок 5</div>

        </div>
      </div>
    </div>
  );
}

export default LandingSearchBox;
